  4	public final class QuickSort {
  5	    private static final int INSERTION_SORT_THRESHOLD = 16;
  6	
  7	    private QuickSort() {
  8	        // Utility class.
  9	    }
 10	
 11	    public static void sort(int[] values) {
 12	        Objects.requireNonNull(values, "values");
 13	        sortRange(values, 0, values.length);
 14	    }
 15	
 16	    public static void sort(int[] values, int fromIndex, int toIndexExclusive) {
 17	        Objects.requireNonNull(values, "values");
 18	        sortRange(values, fromIndex, toIndexExclusive);
 19	    }
 20	
 21	    private static void sortRange(int[] values, int fromIndex, int toIndexExclusive) {
 22	        Objects.checkFromToIndex(fromIndex, toIndexExclusive, values.length);
 23	        if (toIndexExclusive - fromIndex < 2) {
 24	            return;
 25	        }
 26	
 27	        quickSort(values, fromIndex, toIndexExclusive);
 28	    }
 29	
 30	    private static void quickSort(int[] values, int left, int rightExclusive) {
 31	        RangeStack pendingRanges = new RangeStack();
 32	        pendingRanges.push(left, rightExclusive);
 33	
 34	        while (pendingRanges.hasPendingRanges()) {
 35	            Range range = pendingRanges.pop();
 36	            left = range.left();
 37	            rightExclusive = range.rightExclusive();
 38	
 39	            while (rightExclusive - left > INSERTION_SORT_THRESHOLD) {
 40	                Partition partition = partition(values, left, rightExclusive);
 41	                Range lessThanRange = new Range(left, partition.lessThanEndExclusive());
 42	                Range greaterThanRange = new Range(partition.greaterThanStart(), rightExclusive);
 43	
 44	                if (lessThanRange.length() < greaterThanRange.length()) {
 45	                    if (greaterThanRange.length() > 1) {
 46	                        pendingRanges.push(greaterThanRange.left(), greaterThanRange.rightExclusive());
 47	                    }
 48	                    rightExclusive = lessThanRange.rightExclusive();
 49	                } else {
 50	                    if (lessThanRange.length() > 1) {
 51	                        pendingRanges.push(lessThanRange.left(), lessThanRange.rightExclusive());
 52	                    }
 53	                    left = greaterThanRange.left();
 54	                }
 55	            }
 56	
 57	            insertionSort(values, left, rightExclusive);
 58	        }
 59	    }
 60	
 61	    private static Partition partition(int[] values, int left, int rightExclusive) {
 62	        int pivot = choosePivotValue(values, left, rightExclusive);
 63	        int lessThan = left;
 64	        int index = left;
 65	        int greaterThan = rightExclusive - 1;
 66	
 67	        while (index <= greaterThan) {
 68	            int current = values[index];
 69	            if (current < pivot) {
 70	                swap(values, lessThan, index);
 71	                lessThan++;
 72	                index++;
 73	            } else if (current > pivot) {
 74	                swap(values, index, greaterThan);
 75	                greaterThan--;
 76	            } else {
 77	                index++;
 78	            }
 79	        }
 80	
 81	        return new Partition(lessThan, greaterThan + 1);
 82	    }
 83	
 84	    private static int choosePivotValue(int[] values, int left, int rightExclusive) {
 85	        int middle = left + ((rightExclusive - left - 1) >>> 1);
 86	        int right = rightExclusive - 1;
 87	
 88	        int leftValue = values[left];
 89	        int middleValue = values[middle];
 90	        int rightValue = values[right];
 91	
 92	        if (leftValue < middleValue) {
 93	            if (middleValue < rightValue) {
 94	                return middleValue;
 95	            }
 96	            return Math.max(leftValue, rightValue);
 97	        }
 98	
 99	        if (leftValue < rightValue) {
100	            return leftValue;
101	        }
102	
103	        return Math.max(middleValue, rightValue);
104	    }
105	
106	    private static void insertionSort(int[] values, int left, int rightExclusive) {
107	        for (int index = left + 1; index < rightExclusive; index++) {
108	            int currentValue = values[index];
109	            int position = index - 1;
110	
111	            while (position >= left && values[position] > currentValue) {
112	                values[position + 1] = values[position];
113	                position--;
114	            }
115	
116	            values[position + 1] = currentValue;
117	        }
118	    }
119	
120	    private static void swap(int[] values, int first, int second) {
121	        int temp = values[first];
122	        values[first] = values[second];
123	        values[second] = temp;
124	    }
125	
126	    private record Partition(int lessThanEndExclusive, int greaterThanStart) {}
127	
128	    private record Range(int left, int rightExclusive) {
129	        private int length() {
130	            return rightExclusive - left;
131	        }
132	    }
133	
134	    private static final class RangeStack {
135	        private int[] lefts = new int[16];
136	        private int[] rights = new int[16];
137	        private int size;
138	
139	        private void push(int left, int rightExclusive) {
140	            ensureCapacity();
141	            lefts[size] = left;
142	            rights[size] = rightExclusive;
143	            size++;
144	        }
145	
146	        private Range pop() {
147	            size--;
148	            return new Range(lefts[size], rights[size]);
149	        }
150	
151	        private boolean hasPendingRanges() {
152	            return size > 0;
153	        }
154	
155	        private void ensureCapacity() {
156	            if (size < lefts.length) {
157	                return;
158	            }
159	
160	            lefts = Arrays.copyOf(lefts, lefts.length << 1);
161	            rights = Arrays.copyOf(rights, rights.length << 1);
162	        }
163	    }
164	}

