15	    private static final List<TestCase> TEST_CASES = List.of(
16	            new TestCase("sort whole array", QuickSortTest::shouldSortWholeArray),
17	            new TestCase("sort requested range", QuickSortTest::shouldSortOnlyRequestedRange),
18	            new TestCase("handle duplicates and empty input", QuickSortTest::shouldHandleDuplicatesAndEmptyInputs),
19	            new TestCase("sort many duplicates", QuickSortTest::shouldSortManyDuplicates),
20	            new TestCase("reject invalid ranges", QuickSortTest::shouldRejectInvalidRanges));
