48	    }
49	
50	    private static void shouldRejectInvalidRanges() {
51	        expectThrows(IndexOutOfBoundsException.class, () -> QuickSort.sort(new int[] {1, 2, 3}, -1, 2));
52	        expectThrows(IndexOutOfBoundsException.class, () -> QuickSort.sort(new int[] {1, 2, 3}, 0, 4));
53	        expectThrows(IndexOutOfBoundsException.class, () -> QuickSort.sort(new int[] {1, 2, 3}, 2, 1));
54	    }
